export interface SsoTokenInspection {
	providerId: string;
	claimName: string;
	claims: Record<string, unknown> | null;
	issuedAt: Date | null;
	expiresAt: Date | null;
	groups: string[];
	matchedGroups: string[];
	resolvedRole: UserRole | null;
